PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS hr_departments (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,code TEXT NOT NULL,name TEXT NOT NULL,manager_employee_id TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS hr_employees (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,contact_id TEXT REFERENCES contacts(id) ON DELETE SET NULL,school_staff_id TEXT,department_id TEXT REFERENCES hr_departments(id) ON DELETE SET NULL,employee_number TEXT NOT NULL,job_title TEXT,employment_type TEXT NOT NULL DEFAULT 'permanent',employment_status TEXT NOT NULL DEFAULT 'active',hire_date TEXT NOT NULL,termination_date TEXT,manager_employee_id TEXT REFERENCES hr_employees(id) ON DELETE SET NULL,work_email TEXT,work_phone TEXT,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,employee_number),UNIQUE(organization_id,user_id),UNIQUE(organization_id,contact_id),UNIQUE(organization_id,school_staff_id));
CREATE INDEX IF NOT EXISTS hr_employees_org_status_idx ON hr_employees(organization_id,employment_status,department_id);
CREATE TABLE IF NOT EXISTS hr_leave_types (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,code TEXT NOT NULL,name TEXT NOT NULL,paid INTEGER NOT NULL DEFAULT 1,annual_days_micros INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS hr_leave_requests (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,employee_id TEXT NOT NULL REFERENCES hr_employees(id) ON DELETE CASCADE,leave_type_id TEXT NOT NULL REFERENCES hr_leave_types(id) ON DELETE RESTRICT,starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,days_micros INTEGER NOT NULL,reason TEXT,status TEXT NOT NULL DEFAULT 'pending',requested_by TEXT REFERENCES users(id) ON DELETE SET NULL,reviewed_by TEXT REFERENCES users(id) ON DELETE SET NULL,reviewed_at TEXT,review_notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS hr_leave_org_status_idx ON hr_leave_requests(organization_id,status,starts_on);
CREATE TABLE IF NOT EXISTS hr_onboarding_tasks (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,employee_id TEXT NOT NULL REFERENCES hr_employees(id) ON DELETE CASCADE,title TEXT NOT NULL,due_date TEXT,status TEXT NOT NULL DEFAULT 'pending',assigned_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,completed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
